import React, { useMemo, useState } from 'react';
import Layout from '../components/Layout';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  FormControl,
  Grid,
  IconButton,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography
} from '@mui/material';
import { Add, Clear, Delete, Edit, Groups, School } from '@mui/icons-material';
import { useData } from '../context/DataContext';

export default function SeriesTurmasPage() {
  const {
    seriesAcademicas,
    turmasAcademicas,
    clientes,
    adicionarSerieAcademica,
    atualizarSerieAcademica,
    removerSerieAcademica,
    adicionarTurmaAcademica,
    atualizarTurmaAcademica,
    removerTurmaAcademica
  } = useData();

  const [serieEmEdicao, setSerieEmEdicao] = useState(null);
  const [turmaEmEdicao, setTurmaEmEdicao] = useState(null);

  const [serieForm, setSerieForm] = useState({
    nomeSerie: '',
    anoLetivo: String(new Date().getFullYear()),
    descricao: ''
  });

  const [turmaForm, setTurmaForm] = useState({
    nomeTurma: '',
    serieId: '',
    anoLetivo: String(new Date().getFullYear()),
    turno: ''
  });

  const seriesOrdenadas = useMemo(() => {
    return [...seriesAcademicas].sort((a, b) => {
      const anoA = String(a.anoLetivo || '');
      const anoB = String(b.anoLetivo || '');
      if (anoA !== anoB) return anoB.localeCompare(anoA, 'pt-BR');
      return String(a.nomeSerie || '').localeCompare(String(b.nomeSerie || ''), 'pt-BR');
    });
  }, [seriesAcademicas]);

  const turmasOrdenadas = useMemo(() => {
    return [...turmasAcademicas].sort((a, b) => {
      const serieA = String(a.nomeSerie || '');
      const serieB = String(b.nomeSerie || '');
      if (serieA !== serieB) return serieA.localeCompare(serieB, 'pt-BR');
      return String(a.nomeTurma || '').localeCompare(String(b.nomeTurma || ''), 'pt-BR');
    });
  }, [turmasAcademicas]);

  const contadores = useMemo(() => {
    const alunosComTurma = clientes.filter((cliente) => {
      const isAluno = String(cliente.tipo || '').toLowerCase() === 'aluno';
      const temTurma = String(cliente.turma || '').trim().length > 0 || String(cliente.turmaId || '').length > 0;
      return isAluno && temTurma;
    }).length;

    return {
      series: seriesAcademicas.length,
      turmas: turmasAcademicas.length,
      alunosComTurma
    };
  }, [seriesAcademicas, turmasAcademicas, clientes]);

  const getTotalTurmasDaSerie = (serieId) => {
    return turmasAcademicas.filter((turma) => String(turma.serieId) === String(serieId)).length;
  };

  const getTotalAlunosDaTurma = (turma) => {
    return clientes.filter((cliente) => {
      const aluno = String(cliente.tipo || '').toLowerCase() === 'aluno';
      if (!aluno) return false;

      const porId = String(cliente.turmaId || '') === String(turma.id);
      const porNome = String(cliente.turma || '').trim() === String(turma.nomeTurma || '').trim();
      return porId || porNome;
    }).length;
  };

  const limparSerieForm = () => {
    setSerieEmEdicao(null);
    setSerieForm({
      nomeSerie: '',
      anoLetivo: String(new Date().getFullYear()),
      descricao: ''
    });
  };

  const limparTurmaForm = () => {
    setTurmaEmEdicao(null);
    setTurmaForm({
      nomeTurma: '',
      serieId: '',
      anoLetivo: String(new Date().getFullYear()),
      turno: ''
    });
  };

  const salvarSerie = () => {
    if (!serieForm.nomeSerie.trim()) {
      alert('Informe o nome da série.');
      return;
    }

    if (serieEmEdicao) {
      atualizarSerieAcademica(serieEmEdicao, serieForm);
    } else {
      adicionarSerieAcademica(serieForm);
    }

    limparSerieForm();
  };

  const salvarTurma = () => {
    if (!turmaForm.nomeTurma.trim()) {
      alert('Informe o nome da turma.');
      return;
    }

    if (!turmaForm.serieId) {
      alert('Selecione a série da turma.');
      return;
    }

    if (turmaEmEdicao) {
      atualizarTurmaAcademica(turmaEmEdicao, turmaForm);
    } else {
      adicionarTurmaAcademica(turmaForm);
    }

    limparTurmaForm();
  };

  const editarSerie = (serie) => {
    setSerieEmEdicao(serie.id);
    setSerieForm({
      nomeSerie: serie.nomeSerie || '',
      anoLetivo: serie.anoLetivo || String(new Date().getFullYear()),
      descricao: serie.descricao || ''
    });
  };

  const editarTurma = (turma) => {
    setTurmaEmEdicao(turma.id);
    setTurmaForm({
      nomeTurma: turma.nomeTurma || '',
      serieId: String(turma.serieId || ''),
      anoLetivo: turma.anoLetivo || String(new Date().getFullYear()),
      turno: turma.turno || ''
    });
  };

  return (
    <Layout title="Séries e Turmas">
      <Grid container spacing={2} sx={{ mb: 2 }}>
        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent>
              <Typography variant="caption" color="text.secondary">Séries cadastradas</Typography>
              <Typography variant="h5"><School sx={{ mr: 0.5, verticalAlign: 'middle' }} />{contadores.series}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent>
              <Typography variant="caption" color="text.secondary">Turmas cadastradas</Typography>
              <Typography variant="h5"><Groups sx={{ mr: 0.5, verticalAlign: 'middle' }} />{contadores.turmas}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Card>
            <CardContent>
              <Typography variant="caption" color="text.secondary">Alunos alocados em turma</Typography>
              <Typography variant="h5">{contadores.alunosComTurma}</Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <Grid container spacing={2}>
        <Grid item xs={12} lg={6}>
          <Card sx={{ mb: 2 }}>
            <CardContent>
              <Typography variant="h6" sx={{ mb: 2 }}>
                {serieEmEdicao ? 'Editar Série' : 'Cadastrar Série'}
              </Typography>

              <Grid container spacing={2}>
                <Grid item xs={12} md={7}>
                  <TextField
                    fullWidth
                    label="Série/Ano"
                    value={serieForm.nomeSerie}
                    onChange={(e) => setSerieForm({ ...serieForm, nomeSerie: e.target.value })}
                    placeholder="Ex: 6º Ano, 1ª Série"
                  />
                </Grid>
                <Grid item xs={12} md={5}>
                  <TextField
                    fullWidth
                    label="Ano Letivo"
                    value={serieForm.anoLetivo}
                    onChange={(e) => setSerieForm({ ...serieForm, anoLetivo: e.target.value })}
                    placeholder="2026"
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="Descrição"
                    value={serieForm.descricao}
                    onChange={(e) => setSerieForm({ ...serieForm, descricao: e.target.value })}
                    placeholder="Opcional"
                  />
                </Grid>
                <Grid item xs={12}>
                  <Box sx={{ display: 'flex', gap: 1 }}>
                    <Button variant="contained" startIcon={<Add />} onClick={salvarSerie}>
                      {serieEmEdicao ? 'Salvar Série' : 'Adicionar Série'}
                    </Button>
                    {serieEmEdicao && (
                      <Button variant="outlined" color="inherit" startIcon={<Clear />} onClick={limparSerieForm}>
                        Cancelar edição
                      </Button>
                    )}
                  </Box>
                </Grid>
              </Grid>
            </CardContent>
          </Card>

          <TableContainer component={Paper}>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Série</TableCell>
                  <TableCell>Ano Letivo</TableCell>
                  <TableCell>Turmas</TableCell>
                  <TableCell align="right">Ações</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {seriesOrdenadas.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={4} align="center">
                      <Typography color="text.secondary">Nenhuma série cadastrada.</Typography>
                    </TableCell>
                  </TableRow>
                ) : (
                  seriesOrdenadas.map((serie) => (
                    <TableRow key={serie.id} hover>
                      <TableCell>{serie.nomeSerie}</TableCell>
                      <TableCell>{serie.anoLetivo || '-'}</TableCell>
                      <TableCell>
                        <Chip size="small" label={getTotalTurmasDaSerie(serie.id)} />
                      </TableCell>
                      <TableCell align="right">
                        <IconButton size="small" onClick={() => editarSerie(serie)}>
                          <Edit fontSize="small" />
                        </IconButton>
                        <IconButton
                          size="small"
                          color="error"
                          onClick={() => {
                            if (window.confirm('Deseja remover esta série?')) {
                              removerSerieAcademica(serie.id);
                            }
                          }}
                        >
                          <Delete fontSize="small" />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </Grid>

        <Grid item xs={12} lg={6}>
          <Card sx={{ mb: 2 }}>
            <CardContent>
              <Typography variant="h6" sx={{ mb: 2 }}>
                {turmaEmEdicao ? 'Editar Turma' : 'Cadastrar Turma'}
              </Typography>

              <Grid container spacing={2}>
                <Grid item xs={12} md={6}>
                  <FormControl fullWidth>
                    <InputLabel>Série</InputLabel>
                    <Select
                      value={turmaForm.serieId}
                      label="Série"
                      onChange={(e) => {
                        const serieId = e.target.value;
                        const serie = seriesAcademicas.find((item) => String(item.id) === String(serieId));
                        setTurmaForm({
                          ...turmaForm,
                          serieId,
                          anoLetivo: serie?.anoLetivo || turmaForm.anoLetivo
                        });
                      }}
                    >
                      {seriesOrdenadas.map((serie) => (
                        <MenuItem key={serie.id} value={String(serie.id)}>
                          {serie.nomeSerie} {serie.anoLetivo ? `(${serie.anoLetivo})` : ''}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Turma"
                    value={turmaForm.nomeTurma}
                    onChange={(e) => setTurmaForm({ ...turmaForm, nomeTurma: e.target.value })}
                    placeholder="Ex: A, B, Integral"
                  />
                </Grid>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Ano Letivo"
                    value={turmaForm.anoLetivo}
                    onChange={(e) => setTurmaForm({ ...turmaForm, anoLetivo: e.target.value })}
                  />
                </Grid>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Turno"
                    value={turmaForm.turno}
                    onChange={(e) => setTurmaForm({ ...turmaForm, turno: e.target.value })}
                    placeholder="Manhã, Tarde, Noite"
                  />
                </Grid>
                <Grid item xs={12}>
                  <Box sx={{ display: 'flex', gap: 1 }}>
                    <Button variant="contained" startIcon={<Add />} onClick={salvarTurma}>
                      {turmaEmEdicao ? 'Salvar Turma' : 'Adicionar Turma'}
                    </Button>
                    {turmaEmEdicao && (
                      <Button variant="outlined" color="inherit" startIcon={<Clear />} onClick={limparTurmaForm}>
                        Cancelar edição
                      </Button>
                    )}
                  </Box>
                </Grid>
              </Grid>
            </CardContent>
          </Card>

          <TableContainer component={Paper}>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Turma</TableCell>
                  <TableCell>Série</TableCell>
                  <TableCell>Ano</TableCell>
                  <TableCell>Alunos</TableCell>
                  <TableCell align="right">Ações</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {turmasOrdenadas.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={5} align="center">
                      <Typography color="text.secondary">Nenhuma turma cadastrada.</Typography>
                    </TableCell>
                  </TableRow>
                ) : (
                  turmasOrdenadas.map((turma) => (
                    <TableRow key={turma.id} hover>
                      <TableCell>
                        <Typography variant="body2" fontWeight="bold">{turma.nomeTurma}</Typography>
                        {turma.turno && (
                          <Typography variant="caption" color="text.secondary">{turma.turno}</Typography>
                        )}
                      </TableCell>
                      <TableCell>{turma.nomeSerie || '-'}</TableCell>
                      <TableCell>{turma.anoLetivo || '-'}</TableCell>
                      <TableCell>
                        <Chip size="small" label={getTotalAlunosDaTurma(turma)} />
                      </TableCell>
                      <TableCell align="right">
                        <IconButton size="small" onClick={() => editarTurma(turma)}>
                          <Edit fontSize="small" />
                        </IconButton>
                        <IconButton
                          size="small"
                          color="error"
                          onClick={() => {
                            if (window.confirm('Deseja remover esta turma?')) {
                              removerTurmaAcademica(turma.id);
                            }
                          }}
                        >
                          <Delete fontSize="small" />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </Grid>
      </Grid>

      {seriesAcademicas.length === 0 && (
        <Alert severity="info" sx={{ mt: 2 }}>
          Cadastre ao menos uma série para começar a organizar suas turmas e alunos.
        </Alert>
      )}
    </Layout>
  );
}
